-- Local test fixture derived from the user-supplied database diagnostics.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE TABLE auth.users(id uuid primary key); CREATE TABLE public.stories(id bigint primary key); CREATE TABLE public.chapters(id bigint primary key); CREATE TABLE public.paragraphs(id bigint primary key);
CREATE TABLE public."comments" ("id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, "paragraph_id" bigint, "user_id" uuid NOT NULL, "content" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "parent_id" bigint, "reply_to_user_id" uuid, "scope" text DEFAULT 'story'::text, "story_id" bigint, "chapter_index" integer, "paragraph_index" integer, "edited_at" timestamptz);
CREATE TABLE public."comment_likes" ("id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, "comment_id" bigint NOT NULL, "user_id" uuid NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."comment_mentions" ("id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, "comment_id" bigint NOT NULL, "mentioned_user_id" uuid NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."notifications" ("id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, "user_id" uuid NOT NULL, "actor_id" uuid, "type" text NOT NULL, "story_id" bigint, "chapter_id" bigint, "comment_id" bigint, "is_read" boolean DEFAULT false NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."profiles" ("id" uuid NOT NULL, "display_name" text, "avatar_url" text, "role" text DEFAULT 'reader'::text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "bio" text, "saved_stories_public" boolean DEFAULT false NOT NULL);
ALTER TABLE public."comment_likes" ADD CONSTRAINT "comment_likes_pkey" PRIMARY KEY (id);
ALTER TABLE public."comment_mentions" ADD CONSTRAINT "comment_mentions_pkey" PRIMARY KEY (id);
ALTER TABLE public."comments" ADD CONSTRAINT "comments_pkey" PRIMARY KEY (id);
ALTER TABLE public."notifications" ADD CONSTRAINT "notifications_pkey" PRIMARY KEY (id);
ALTER TABLE public."profiles" ADD CONSTRAINT "profiles_pkey" PRIMARY KEY (id);
ALTER TABLE public."comment_likes" ADD CONSTRAINT "comment_likes_comment_id_user_id_key" UNIQUE (comment_id, user_id);
ALTER TABLE public."comment_mentions" ADD CONSTRAINT "comment_mentions_comment_id_mentioned_user_id_key" UNIQUE (comment_id, mentioned_user_id);
ALTER TABLE public."comments" ADD CONSTRAINT "comments_scope_check" CHECK ((scope = ANY (ARRAY['story'::text, 'chapter'::text, 'paragraph'::text])));
ALTER TABLE public."notifications" ADD CONSTRAINT "notifications_type_check" CHECK ((type = ANY (ARRAY['story_like'::text, 'comment'::text, 'reply'::text, 'mention'::text, 'comment_like'::text])));
ALTER TABLE public."profiles" ADD CONSTRAINT "profiles_role_check" CHECK ((role = ANY (ARRAY['reader'::text, 'admin'::text])));
ALTER TABLE public."comment_likes" ADD CONSTRAINT "comment_likes_comment_id_fkey" FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE;
ALTER TABLE public."comment_likes" ADD CONSTRAINT "comment_likes_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public."comment_mentions" ADD CONSTRAINT "comment_mentions_comment_id_fkey" FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE;
ALTER TABLE public."comment_mentions" ADD CONSTRAINT "comment_mentions_mentioned_user_id_fkey" FOREIGN KEY (mentioned_user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public."comments" ADD CONSTRAINT "comments_paragraph_id_fkey" FOREIGN KEY (paragraph_id) REFERENCES paragraphs(id) ON DELETE CASCADE;
ALTER TABLE public."comments" ADD CONSTRAINT "comments_parent_id_fkey" FOREIGN KEY (parent_id) REFERENCES comments(id) ON DELETE CASCADE;
ALTER TABLE public."comments" ADD CONSTRAINT "comments_reply_to_user_id_fkey" FOREIGN KEY (reply_to_user_id) REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE public."comments" ADD CONSTRAINT "comments_story_id_fkey" FOREIGN KEY (story_id) REFERENCES stories(id) ON DELETE CASCADE;
ALTER TABLE public."comments" ADD CONSTRAINT "comments_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public."notifications" ADD CONSTRAINT "notifications_actor_id_fkey" FOREIGN KEY (actor_id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public."notifications" ADD CONSTRAINT "notifications_chapter_id_fkey" FOREIGN KEY (chapter_id) REFERENCES chapters(id) ON DELETE CASCADE;
ALTER TABLE public."notifications" ADD CONSTRAINT "notifications_comment_id_fkey" FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE;
ALTER TABLE public."notifications" ADD CONSTRAINT "notifications_story_id_fkey" FOREIGN KEY (story_id) REFERENCES stories(id) ON DELETE CASCADE;
ALTER TABLE public."notifications" ADD CONSTRAINT "notifications_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public."profiles" ADD CONSTRAINT "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public."comment_likes" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."comment_mentions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."comments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."notifications" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."profiles" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Comment likes are viewable" ON public."comment_likes" FOR SELECT TO PUBLIC USING (true);
CREATE POLICY "Users can like comments" ON public."comment_likes" FOR INSERT TO "authenticated" WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "Users can remove own comment likes" ON public."comment_likes" FOR DELETE TO "authenticated" USING ((user_id = auth.uid()));
CREATE POLICY "Authenticated users can create mentions" ON public."comment_mentions" FOR INSERT TO "authenticated" WITH CHECK (true);
CREATE POLICY "Mentions are viewable" ON public."comment_mentions" FOR SELECT TO PUBLIC USING (true);
CREATE POLICY "Comments are publicly viewable" ON public."comments" FOR SELECT TO "anon","authenticated" USING (true);
CREATE POLICY "Comments are viewable" ON public."comments" FOR SELECT TO PUBLIC USING (true);
CREATE POLICY "Users create own comments" ON public."comments" FOR INSERT TO "authenticated" WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "Users or admin delete comments" ON public."comments" FOR DELETE TO "authenticated" USING (((user_id = auth.uid()) OR is_admin()));
CREATE POLICY "Users update own comments" ON public."comments" FOR UPDATE TO "authenticated" USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "nca comments own delete" ON public."comments" FOR DELETE TO "authenticated" USING ((auth.uid() = user_id));
CREATE POLICY "nca comments own insert" ON public."comments" FOR INSERT TO "authenticated" WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "nca comments own update" ON public."comments" FOR UPDATE TO "authenticated" USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "nca comments public read" ON public."comments" FOR SELECT TO "anon","authenticated" USING (true);
CREATE POLICY "Authenticated users can create notifications" ON public."notifications" FOR INSERT TO "authenticated" WITH CHECK (((actor_id = auth.uid()) AND (user_id <> auth.uid())));
CREATE POLICY "Users can delete own notifications" ON public."notifications" FOR DELETE TO "authenticated" USING ((user_id = auth.uid()));
CREATE POLICY "Users can mark own notifications read" ON public."notifications" FOR UPDATE TO "authenticated" USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "Users can view own notifications" ON public."notifications" FOR SELECT TO "authenticated" USING ((user_id = auth.uid()));
CREATE POLICY "Profiles are viewable" ON public."profiles" FOR SELECT TO PUBLIC USING (true);
CREATE POLICY "Users can insert own profile" ON public."profiles" FOR INSERT TO "authenticated" WITH CHECK ((auth.uid() = id));
CREATE POLICY "Users can update own profile" ON public."profiles" FOR UPDATE TO "authenticated" USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));
CREATE POLICY "Users update own profile" ON public."profiles" FOR UPDATE TO "authenticated" USING ((id = auth.uid())) WITH CHECK (((id = auth.uid()) AND (role = ( SELECT p.role
   FROM profiles p
  WHERE (p.id = auth.uid())))));
GRANT USAGE ON SCHEMA public,auth TO anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO anon;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO authenticated;
